"""Average of Levels in Binary Tree — BFS with a per-level sum.

Time: O(n)   Space: O(width)
"""
from collections import deque
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def averageOfLevels(self, root) -> List[float]:
        out, queue = [], deque([root])
        while queue:
            total, size = 0, len(queue)
            for _ in range(size):
                node = queue.popleft()
                total += node.val
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            out.append(total / size)
        return out
